-- `optimize_push_subcolumns_into_subqueries` must not change the result of these queries: every query runs
-- with the setting disabled and enabled, and both results must be the same.

SET enable_analyzer = 1;

DROP TABLE IF EXISTS t_pushdown_l;
DROP TABLE IF EXISTS t_pushdown_r;
DROP TABLE IF EXISTS t_pushdown_s;
DROP TABLE IF EXISTS t_pushdown_sum_map;
DROP TABLE IF EXISTS t_pushdown_coalescing;
DROP TABLE IF EXISTS t_pushdown_nested;

-- Outer joins: the subcolumn of a value generated by the join is not the default value of the subcolumn.
CREATE TABLE t_pushdown_l (k UInt64) ENGINE = MergeTree ORDER BY k;
CREATE TABLE t_pushdown_r (k UInt64, n Nullable(Int32), arr Array(UInt8)) ENGINE = MergeTree ORDER BY k;
INSERT INTO t_pushdown_l VALUES (1), (2);
INSERT INTO t_pushdown_r VALUES (2, 7, [1, 2]), (3, 8, [3]);

SELECT 'left join';
SELECT k, getSubcolumn(n, 'null') FROM (SELECT l.k AS k, r.n AS n FROM t_pushdown_l AS l LEFT JOIN t_pushdown_r AS r ON l.k = r.k)
ORDER BY k SETTINGS join_use_nulls = 0, optimize_push_subcolumns_into_subqueries = 0;
SELECT k, getSubcolumn(n, 'null') FROM (SELECT l.k AS k, r.n AS n FROM t_pushdown_l AS l LEFT JOIN t_pushdown_r AS r ON l.k = r.k)
ORDER BY k SETTINGS join_use_nulls = 0, optimize_push_subcolumns_into_subqueries = 1;
SELECT k, arr.size0 FROM (SELECT l.k AS k, r.arr AS arr FROM t_pushdown_l AS l LEFT JOIN t_pushdown_r AS r ON l.k = r.k)
ORDER BY k SETTINGS join_use_nulls = 1, optimize_push_subcolumns_into_subqueries = 0;
SELECT k, arr.size0 FROM (SELECT l.k AS k, r.arr AS arr FROM t_pushdown_l AS l LEFT JOIN t_pushdown_r AS r ON l.k = r.k)
ORDER BY k SETTINGS join_use_nulls = 1, optimize_push_subcolumns_into_subqueries = 1;

SELECT 'right join';
SELECT k, getSubcolumn(n, 'null') FROM (SELECT r.k AS k, l.k AS lk, l.n AS n FROM t_pushdown_r AS l RIGHT JOIN t_pushdown_r AS r ON l.k = r.k + 1)
ORDER BY k SETTINGS join_use_nulls = 0, optimize_push_subcolumns_into_subqueries = 0;
SELECT k, getSubcolumn(n, 'null') FROM (SELECT r.k AS k, l.k AS lk, l.n AS n FROM t_pushdown_r AS l RIGHT JOIN t_pushdown_r AS r ON l.k = r.k + 1)
ORDER BY k SETTINGS join_use_nulls = 0, optimize_push_subcolumns_into_subqueries = 1;

SELECT 'left join below cross join';
CREATE TABLE t_pushdown_s (x UInt64) ENGINE = MergeTree ORDER BY x;
INSERT INTO t_pushdown_s VALUES (1);
SELECT k, getSubcolumn(n, 'null') FROM (SELECT l.k AS k, r.n AS n FROM t_pushdown_l AS l LEFT JOIN t_pushdown_r AS r ON l.k = r.k CROSS JOIN t_pushdown_s)
ORDER BY k SETTINGS join_use_nulls = 0, optimize_push_subcolumns_into_subqueries = 0;
SELECT k, getSubcolumn(n, 'null') FROM (SELECT l.k AS k, r.n AS n FROM t_pushdown_l AS l LEFT JOIN t_pushdown_r AS r ON l.k = r.k CROSS JOIN t_pushdown_s)
ORDER BY k SETTINGS join_use_nulls = 0, optimize_push_subcolumns_into_subqueries = 1;
SELECT k, arr.size0 FROM (SELECT l.k AS k, r.arr AS arr FROM t_pushdown_s, t_pushdown_l AS l LEFT JOIN t_pushdown_r AS r ON l.k = r.k)
ORDER BY k SETTINGS join_use_nulls = 1, optimize_push_subcolumns_into_subqueries = 0;
SELECT k, arr.size0 FROM (SELECT l.k AS k, r.arr AS arr FROM t_pushdown_s, t_pushdown_l AS l LEFT JOIN t_pushdown_r AS r ON l.k = r.k)
ORDER BY k SETTINGS join_use_nulls = 1, optimize_push_subcolumns_into_subqueries = 1;

-- `FINAL`: the merge of a subcolumn is not that subcolumn of the merge of the column.
CREATE TABLE t_pushdown_sum_map (k UInt64, m SimpleAggregateFunction(sumMap, Map(String, UInt64)))
ENGINE = AggregatingMergeTree ORDER BY k;
SYSTEM STOP MERGES t_pushdown_sum_map;
INSERT INTO t_pushdown_sum_map VALUES (1, {'a': 1});
INSERT INTO t_pushdown_sum_map VALUES (1, {'b': 2});

SELECT 'final';
SELECT m.keys FROM (SELECT m FROM t_pushdown_sum_map FINAL) SETTINGS optimize_push_subcolumns_into_subqueries = 0;
SELECT m.keys FROM (SELECT m FROM t_pushdown_sum_map FINAL) SETTINGS optimize_push_subcolumns_into_subqueries = 1;
SELECT m.keys FROM (SELECT m FROM t_pushdown_sum_map) SETTINGS final = 1, optimize_push_subcolumns_into_subqueries = 1;

CREATE TABLE t_pushdown_coalescing (k UInt64, n Nullable(Int32)) ENGINE = CoalescingMergeTree ORDER BY k;
SYSTEM STOP MERGES t_pushdown_coalescing;
INSERT INTO t_pushdown_coalescing VALUES (1, 7);
INSERT INTO t_pushdown_coalescing VALUES (1, NULL);

SELECT n.null FROM (SELECT n FROM t_pushdown_coalescing FINAL) SETTINGS optimize_push_subcolumns_into_subqueries = 0;
SELECT n.null FROM (SELECT n FROM t_pushdown_coalescing FINAL) SETTINGS optimize_push_subcolumns_into_subqueries = 1;

-- A nested subcolumn access after grouping by the parent column.
CREATE TABLE t_pushdown_nested (tup Tuple(a Tuple(b UInt64, c String), z UInt64)) ENGINE = MergeTree ORDER BY tuple();
INSERT INTO t_pushdown_nested VALUES (((1, 'x'), 3)), (((2, 'y'), 4));

SELECT 'nested';
SELECT getSubcolumn(getSubcolumn(r, 'a'), 'b'), count() FROM (SELECT tup AS r FROM t_pushdown_nested)
GROUP BY r ORDER BY ALL SETTINGS optimize_push_subcolumns_into_subqueries = 0;
SELECT getSubcolumn(getSubcolumn(r, 'a'), 'b'), count() FROM (SELECT tup AS r FROM t_pushdown_nested)
GROUP BY r ORDER BY ALL SETTINGS optimize_push_subcolumns_into_subqueries = 1;

-- `group_by_use_nulls` with `GROUPING SETS`, `ROLLUP` and `CUBE`.
SELECT 'group_by_use_nulls';
SELECT tup, tup.a, count() FROM (SELECT tup FROM t_pushdown_nested)
GROUP BY GROUPING SETS ((tup), (tup.a)) ORDER BY ALL SETTINGS group_by_use_nulls = 1, optimize_push_subcolumns_into_subqueries = 0;
SELECT tup, tup.a, count() FROM (SELECT tup FROM t_pushdown_nested)
GROUP BY GROUPING SETS ((tup), (tup.a)) ORDER BY ALL SETTINGS group_by_use_nulls = 1, optimize_push_subcolumns_into_subqueries = 1;
SELECT tup, tup.z, count() FROM (SELECT tup FROM t_pushdown_nested)
GROUP BY GROUPING SETS ((tup), (tup.z)) ORDER BY ALL SETTINGS group_by_use_nulls = 1, optimize_push_subcolumns_into_subqueries = 0;
SELECT tup, tup.z, count() FROM (SELECT tup FROM t_pushdown_nested)
GROUP BY GROUPING SETS ((tup), (tup.z)) ORDER BY ALL SETTINGS group_by_use_nulls = 1, optimize_push_subcolumns_into_subqueries = 1;
SELECT tup, tup.z, count() FROM (SELECT tup FROM t_pushdown_nested)
GROUP BY ROLLUP(tup, tup.z) ORDER BY ALL SETTINGS group_by_use_nulls = 1, optimize_push_subcolumns_into_subqueries = 0;
SELECT tup, tup.z, count() FROM (SELECT tup FROM t_pushdown_nested)
GROUP BY ROLLUP(tup, tup.z) ORDER BY ALL SETTINGS group_by_use_nulls = 1, optimize_push_subcolumns_into_subqueries = 1;
SELECT tup, tup.z, count() FROM (SELECT tup FROM t_pushdown_nested)
GROUP BY CUBE(tup, tup.z) ORDER BY ALL SETTINGS group_by_use_nulls = 1, optimize_push_subcolumns_into_subqueries = 0;
SELECT tup, tup.z, count() FROM (SELECT tup FROM t_pushdown_nested)
GROUP BY CUBE(tup, tup.z) ORDER BY ALL SETTINGS group_by_use_nulls = 1, optimize_push_subcolumns_into_subqueries = 1;

DROP TABLE t_pushdown_l;
DROP TABLE t_pushdown_r;
DROP TABLE t_pushdown_s;
DROP TABLE t_pushdown_sum_map;
DROP TABLE t_pushdown_coalescing;
DROP TABLE t_pushdown_nested;
